  void ShowCar(){if(preview){preview.SetActive(false);Destroy(preview);}preview=ModelLibrary.Create(CarSpec.All[selectedCar].name,showroom.transform);StoreCar();CarParts.Apply(preview,CurrentCar);ApplyInventoryVisual(preview);foreach(var t in preview.GetComponentsInChildren<Transform>())t.gameObject.layer=8;}
  IEnumerator Begin(){
   if(loading)yield break;loading=true;ClearResults();stuntRewardGranted=false;stuntAward=0;Save();yield return null;Destroy(showroom);if(track)Destroy(track.gameObject);foreach(var v in racers)if(v)Destroy(v.gameObject);foreach(var p in boxes)if(p)Destroy(p.gameObject);foreach(var r in FindObjectsByType<Rocket>())Destroy(r.gameObject);racers.Clear();boxes.Clear();finishedCount=0;
   RushReset();track=new GameObject(stuntMode?"Heartstopper":rushMode?Challenge.name:TrackWorld.Names[mapIndex]).AddComponent<TrackWorld>();if(stuntMode)track.GenerateStunts();else if(rushMode)track.GenerateRush(rushIndex);else {track.Generate(mapIndex);RoadGuideLights.Build(track);}track.BuildMapDetails();track.ConnectFeatures(this);ApplyDeviceQuality();cam.farClipPlane=stuntMode?10000:track.IsAirah?6200:3000;
   for(int i=0;i<=(stuntMode?Mathf.Clamp(stuntAiCount,0,9):rushMode?Challenge.opponents:aiCount);i++){int n=stuntMode||rushMode?0:(TrackWorld.Count-2-i/2*2)%TrackWorld.Count;Vector3 p=stuntMode?track.StuntPosition(-i/2*7)+Vector3.right*(i%2==0?-3:3)+Vector3.up*.55f:rushMode?new Vector3((i%2==0?-1:1)*3,5.55f,-12-i/2*7):track.points[n]+track.Right(n)*(i%2==0?-1:1)*(track.map==1?1.65f:3)+Vector3.up*.55f;var v=new GameObject(i==0?"Player":botNames[(i-1)%botNames.Length]).AddComponent<Vehicle>();v.Initialize(this,i==0?selectedCar:(i-1)%CarSpec.All.Length,i==0,i==0?"You":botNames[(i-1)%botNames.Length],p,Quaternion.LookRotation(track.Forward(n)),i==0?engineLevel:0,i==0?tireLevel:0,i==0?brakeLevel:0);racers.Add(v);if(i==0){player=v;CarParts.Apply(v.model,CurrentCar);ApplyInventoryVisual(v.model);if(rushMode){var fill=new GameObject("Rush car fill").AddComponent<Light>();fill.transform.SetParent(v.transform,false);fill.transform.localPosition=new Vector3(0,4,-2);fill.type=LightType.Point;fill.range=13;fill.intensity=.65f;fill.color=new Color(.66f,.77f,1);if(rushIndex==2)PremiumLighting.Headlights(v.transform,true,1);}if(CurrentCar.starTrail&&SupportStore.Owned("star-trail")){var stars=RaceEffects.Emitter(v.transform,"Starlight boost trail",new Color(.7f,.4f,1),.9f,.18f,1,70);stars.transform.localPosition=Vector3.back*2;stars.gameObject.AddComponent<SupportTrail>();}}else CarParts.Apply(v.model,new SavedCar{body=v.carIndex,paint=(i*3+1)%Paints.Length,accent=(i*2+4)%Paints.Length,wheel=i%10,wheelColor=(i+4)%Paints.Length,glass=i%13,engine=i%11});}
   if(powerups||rushMode||stuntMode)foreach(Vector3 p in track.pickups){var o=RaceEffects.Crate();o.transform.position=p;var box=o.AddComponent<Pickup>();box.game=this;box.home=p;boxes.Add(box);}
   BeginDrivingSkills();raceTime=0;countdown=3.8f;state=State.Countdown;cam.transform.position=player.transform.position-player.transform.forward*9+Vector3.up*4;cam.transform.LookAt(player.transform.position+Vector3.up);cameraVel=Vector3.zero;loading=false;
  }
  public void StartRace(){if(loading)return;Time.timeScale=1;state=State.Countdown;StartCoroutine(Begin());}
  void Update(){
   StartupUpdate();UpdatePhoneInput();
   if(messageTimer>0)messageTimer-=Time.unscaledDeltaTime;
   if(!loading&&state==State.Countdown){countdown-=Time.deltaTime;if(countdown<=0){state=State.Race;RushGo();Toast("Go!");}}
   if(!loading&&RaceSimulationActive){raceTime+=Time.deltaTime;UpdateRacePlaces();}UpdateResultsPresentation();
   RushUpdate();if(Input.GetKeyDown(KeyCode.Escape))HandleBack();
   GarageInput();
   cameraShake=Mathf.Max(0,cameraShake-Time.unscaledDeltaTime);
   if(Environment.GetCommandLineArgs().Contains("-aetherTest"))TestDriver();
  }
  void LateUpdate(){
   if(state==State.Menu&&preview){Vector3 offset=Quaternion.Euler(0,orbit,0)*new Vector3(0,menu=="Garage"?viewHeight:2.8f,menu=="Garage"?zoom:8.5f);cam.transform.position=offset;cam.transform.LookAt(new Vector3(0,.55f,0));cam.transform.rotation*=Quaternion.Euler(0,menu=="Play"?-8:menu=="Garage"?5:0,0);cam.fieldOfView=45;}
   else if(player&&stuntMode){UpdateStuntCamera();}
   else if(player){Vector3 forward=player.transform.forward;if(player.body.linearVelocity.magnitude>4)forward=Vector3.Slerp(forward,player.body.linearVelocity.normalized,.22f);forward.y=0;forward.Normalize();Vector3 desired=player.transform.position-forward*8.6f+Vector3.up*3.9f;if(stuntMode)desired+=player.body.linearVelocity*.09f;if(Vector3.Distance(cam.transform.position,desired)>65){cam.transform.position=desired;cameraVel=Vector3.zero;}cam.transform.position=Vector3.SmoothDamp(cam.transform.position,desired,ref cameraVel,.14f,200,Time.unscaledDeltaTime);Vector3 focus=player.transform.position+player.transform.forward*5+Vector3.up*1.05f;cam.transform.rotation=Quaternion.Slerp(cam.transform.rotation,Quaternion.LookRotation(focus-cam.transform.position),Time.unscaledDeltaTime*10);cam.fieldOfView=Mathf.Lerp(cam.fieldOfView,60+Mathf.Clamp01(player.speed/250)*13+(player.boost>0?7:0),Time.unscaledDeltaTime*3);if(cameraShake>0)cam.transform.position+=UnityEngine.Random.insideUnitSphere*cameraShake*.25f;}
   if(player)foreach(var v in racers)if(v!=player)foreach(var r in v.ShadowRenderers)if(r)r.shadowCastingMode=Vector3.Distance(v.transform.position,cam.transform.position)<5?UnityEngine.Rendering.ShadowCastingMode.ShadowsOnly:UnityEngine.Rendering.ShadowCastingMode.On;
  }
  public void Toast(string s){message=s;messageTimer=3;}
  public void OnFinish(Vehicle v){if(v.finishOrder>0)return;v.finishOrder=++finishedCount;UpdateRacePlaces();if(v==player){AwardDrivingSkills();BeginFinishCelebration();}if(stuntMode){AwardStunts(v);return;}if(rushMode){AwardRush(v);return;}if(v.player){int award=500+Mathf.Max(0,aiCount+2-finishedCount)*80+v.coins*10;circuitAward=award;credits+=award;Save();Toast("Finished! +"+award+" credits");}}
  static Material fxMaterial;static AudioClip impactClip;
  public static Material FXMaterial(){if(fxMaterial)return fxMaterial;var tex=new Texture2D(32,32,TextureFormat.RGBA32,false);var colors=new Color[1024];for(int y=0;y<32;y++)for(int x=0;x<32;x++){float a=Mathf.Clamp01(1-new Vector2(x-15.5f,y-15.5f).magnitude/15.5f);colors[y*32+x]=new Color(1,1,1,a*a);}tex.SetPixels(colors);tex.Apply();fxMaterial=new Material(Shader.Find("Sprites/Default"));fxMaterial.mainTexture=tex;return fxMaterial;}
  public void Burst(Vector3 p,Color c,float amount){var o=new GameObject("Impact sparks");o.transform.position=p;var ps=o.AddComponent<ParticleSystem>();var main=ps.main;main.loop=false;main.startLifetime=.35f;main.startSpeed=7*amount;main.startSize=.16f;main.startColor=c;main.gravityModifier=1;var emission=ps.emission;emission.rateOverTime=0;emission.SetBursts(new[]{new ParticleSystem.Burst(0,(short)(24*amount))});var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Sphere;shape.radius=.2f;ps.GetComponent<ParticleSystemRenderer>().material=FXMaterial();ps.Play();if(player&&Vector3.Distance(p,player.transform.position)<35){if(!impactClip){impactClip=AudioClip.Create("Collision impact",11025,1,44100,false);var samples=new float[11025];var random=new System.Random(42);for(int i=0;i<samples.Length;i++)samples[i]=((float)random.NextDouble()*2-1)*Mathf.Exp(-i/1500f)*.8f;impactClip.SetData(samples,0);}var sound=o.AddComponent<AudioSource>();sound.clip=impactClip;sound.volume=volume*Mathf.Min(.35f,amount*.15f);sound.pitch=.7f+amount*.2f;sound.Play();}Destroy(o,1.5f);}
