   if(state==State.Pause){Panel(0,0,1600,900,.65f);Panel(580,223,440,459);Label("Paused",620,256,360,61,42,null,true);if(Button("Resume",620,353,360,54,true)){state=beforePause;Time.timeScale=1;}if(Button("Restart",620,429,360,54)){StartRace();}if(Button("Game Setup",620,505,360,54)){ReturnMenu();menu="Game Setup";}if(Button("Main Menu",620,581,360,54)){ReturnMenu();menu="Play";}}
   if(state==State.Results){Panel(0,0,1600,900,.75f);Panel(414,115,772,650);Label("Match Results",450,146,700,62,43,null,true);Label(TrackWorld.Names[mapIndex]+" · "+laps+(laps==1?" lap":" laps"),451,212,685,37,22,cyan);Label(player.coins+" coins · "+player.coins*100+" points · +"+player.coins*10+" coin credits",451,244,680,30,18,cyan);var order=racers.OrderBy(v=>v.place).Take(20).ToArray();for(int i=0;i<order.Length;i++){var v=order[i];Label(v.place+"   "+v.driver,453+(i/10)*349,283+(i%10)*31,245,29,18,v.player?cyan:Color.white);Label(v.finished?TimeFormat(v.finishTime):"Not finished",699+(i/10)*349,283+(i%10)*31,104,29,16,muted);}if(Button("Restart",451,662,215,57,true))StartRace();if(Button("Game Setup",681,662,215,57)){ReturnMenu();menu="Game Setup";}if(Button("Main Menu",911,662,235,57))MainMenu();}
  }
  string TimeFormat(float t)=>((int)t/60).ToString("00")+":"+(t%60).ToString("00.00");
  void MiniMap(){Rect r=new Rect(1328,25,244,244);Panel(r.x,r.y,r.width,r.height,.87f);Label("Circuit",1345,36,200,27,17,muted);float mapScale=track.IsAirah?.079f:.25f;Vector2 P(Vector3 p)=>new Vector2(r.x+122+p.x*mapScale,r.y+137-p.z*mapScale);for(int i=0;i<TrackWorld.Count;i+=2){Vector2 p=P(track.points[i]);GUI.color=new Color(.39f,.52f,.64f);GUI.DrawTexture(new Rect(p.x-2,p.y-2,4,4),pixel);}foreach(var v in racers){Vector2 p=P(v.transform.position);GUI.color=v.player?cyan:new Color(1,.50f,.35f);GUI.DrawTexture(new Rect(p.x-4,p.y-4,8,8),pixel);}GUI.color=Color.white;}
  // Optional reproducible smoke test; logs assertions and captures actual rendered frames.
  void TestDriver(){
   testTimer+=Time.unscaledDeltaTime;
   if(testStage==0&&testTimer>4){ScreenCapture.CaptureScreenshot(evidencePath+"/menu.png");testStage++;testTimer=0;}
   else if(testStage==1&&testTimer>1){menu="Garage";ScreenCapture.CaptureScreenshot(evidencePath+"/garage.png");testStage=10;testTimer=0;}
   else if(testStage==10&&testTimer>1){laps=1;StartRace();testStage=2;testTimer=0;}
   else if(testStage==2&&state==State.Race){player.player=false;testStage++;testTimer=0;Debug.Log("AETHER_TEST Race started. cars="+racers.Count+" trackMeters="+track.length);}
   else if(testStage==3&&testTimer>18){ScreenCapture.CaptureScreenshot(evidencePath+"/race-"+mapIndex+".png");Debug.Log("AETHER_TEST after18s speed="+player.speed+" progress="+player.progress+" grounded="+player.grounded+" position="+player.transform.position);player.item="Shield";player.UseItem();Debug.Assert(player.shield>0,"Shield failed");player.item="Boost";player.UseItem();Debug.Assert(player.boost>0,"Boost failed");testStage++;testTimer=0;}
   else if(testStage==4){testFps+=Time.unscaledDeltaTime;testFrames++;if(state==State.Results||testTimer>240){Debug.Log("AETHER_TEST map="+mapIndex+" state="+state+" fps="+(testFrames/testFps)+" "+string.Join("; ",racers.Select(v=>v.driver+" progress="+v.progress.ToString("F1")+" gate="+v.circuitCheckpoint+" finished="+v.finished+" speed="+v.speed.ToString("F1"))));Debug.Assert(state==State.Results,"Race did not finish");ScreenCapture.CaptureScreenshot(evidencePath+"/results-"+mapIndex+".png");testStage++;testTimer=0;}}
   else if(testStage==5&&testTimer>1){if(mapIndex<2){mapIndex++;StartRace();testStage=2;testTimer=0;testFps=0;testFrames=0;}else Application.Quit();}
  }
 }
 public class Pickup:MonoBehaviour {
  public static string ChooseItem(Game game,Vehicle receiver,float roll){bool rival=game.racers.Exists(v=>v&&v!=receiver&&!v.finished);string[] pool=rival?(game.rushMode?RushWeapons:WeaponCatalog.Items):SoloWeapons;return pool[Mathf.Clamp(Mathf.FloorToInt(Mathf.Clamp01(roll)*pool.Length),0,pool.Length-1)];}
  static readonly string[] SoloWeapons={"Boost","Shield"};
  public static readonly string[] RushWeapons={"Rocket","Rocket","Ice Blast","EMP","Oil Slick","Gravity Mine","Shockwave","Pulse","Boost","Shield"};
  public Game game;public Vector3 home;float cooldown;Renderer[] visuals;public bool Available=>cooldown<=0;
  void Start(){visuals=GetComponentsInChildren<Renderer>();}
  void Update(){if(!game.RaceSimulationActive&&game.state!=Game.State.Countdown)return;transform.rotation=Quaternion.Euler(0,Time.time*42,Mathf.Sin(Time.time)*5);transform.position=home+Vector3.up*Mathf.Sin(Time.time*2+home.x)*.2f;
   if(cooldown>0)cooldown-=Time.deltaTime;bool visible=cooldown<=0;foreach(var r in visuals)if(r)r.enabled=visible;if(!visible)return;
   foreach(var v in game.racers)if(!v.finished&&v.item==""&&Vector3.Distance(v.transform.position+Vector3.up,home)<2.7f){v.item=ChooseItem(game,v,UnityEngine.Random.value);cooldown=7;RaceEffects.Debris(home,new Color(.4f,.27f,.12f),10,5);RaceEffects.Burst(home,new Color(.16f,1,.72f),24,5,.2f,.65f);RaceEffects.Ring(home,new Color(.16f,1,.72f),3);foreach(var r in visuals)if(r)r.enabled=false;if(v.player)game.Toast(v.item+(game.phoneMode?" collected · tap Item":" collected · press E"));break;}
  }
 }
